/**
 * Noto Sans Khmer (Khmer-script subset only, weights 400/700), embedded as
 * base64 data URIs.
 *
 * The PDF renderer (pdf.ts) uses @sparticuz/chromium on Vercel, whose
 * bundled Chromium only ships Open Sans (Latin) — no Khmer, no CJK — and
 * there is no OS-level fallback to borrow from either. A @font-face with a
 * remote/local file URL would depend on network access or bundling the file
 * into the serverless function; a data: URI travels inside the HTML string
 * itself, so it renders identically in Puppeteer on Vercel and in a
 * developer's local Chrome. Source: Google Fonts (fonts.googleapis.com),
 * khmer unicode-range subset (U+1780-17FF, U+19E0-19FF, U+200C-200D,
 * U+25CC) — Latin/Chinese glyphs are intentionally left out of this file so
 * it stays small; the browser falls through to Arial/Noto Sans SC in the
 * body font stack for those characters via normal per-glyph font fallback.
 */
export const NOTO_SANS_KHMER_REGULAR_BASE64 =
  '';
export const NOTO_SANS_KHMER_BOLD_BASE64 =
  '';

/** @font-face rules for the Khmer subset above — inline once per document. */
export const KHMER_FONT_FACE_CSS = `
@font-face {
  font-family: "Noto Sans Khmer";
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url(data:font/woff2;base64,${NOTO_SANS_KHMER_REGULAR_BASE64}) format("woff2");
}
@font-face {
  font-family: "Noto Sans Khmer";
  font-style: normal;
  font-weight: 700;
  font-display: block;
  src: url(data:font/woff2;base64,${NOTO_SANS_KHMER_BOLD_BASE64}) format("woff2");
}
`;
